'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),base='releases/v425/',root='releases/v433/';
const old=JSON.parse(fs.readFileSync(base+'manifest.json')),m=JSON.parse(fs.readFileSync(root+'manifest.json'));
assert.equal(m.release,'v433');assert.equal(m.base_release,'v425');
assert.deepEqual(Object.keys(m.files).sort(),Object.keys(old.files).sort());
assert.deepEqual(Object.keys(m.files).concat('manifest.json').sort(),fs.readdirSync(root).sort());
for(const[n,h]of Object.entries(old.files))assert.equal(sha(fs.readFileSync(base+n)),h,'immutable predecessor '+n);
for(const[n,h]of Object.entries(m.files))assert.equal(sha(fs.readFileSync(root+n)),h,'candidate '+n);
assert.equal(m.protected_manifest.sha256,sha(fs.readFileSync(base+'manifest.json')));
const changed=Object.keys(m.files).filter(n=>m.files[n]!==old.files[n]).sort();
assert.deepEqual(changed,['app.html','index.html','lts-v181-regression-closure.js','lts-v227-read-transport.js','lts-v384-startup-1.js','provenance.json']);
const p=JSON.parse(fs.readFileSync(root+'provenance.json'));
for(const key of ['financial_values_changed','new_financial_reads_or_writes','query_arguments_changed','cache_or_auth_policy_changed'])assert.equal(p[key],false);
assert.equal(p.active_review_budget_ms,22000);assert.equal(p.existing_admission_budget_ms,60000);
const transport=fs.readFileSync(root+'lts-v227-read-transport.js','utf8');
assert(transport.includes("name==='lts_browser_expense_review_queue_v229'?22000:"));
assert(transport.includes('setTimeout(item.cancel,60000)'));assert(transport.includes('generation===revision'));
assert.deepEqual(JSON.parse(fs.readFileSync('mobile/current.json')),{release:'v433',entry:'../releases/v433/app.html'});
assert(fs.readFileSync(root+'app.html','utf8').includes('V433'));
console.log(JSON.stringify({pass:true,release:'v433',assets:Object.keys(m.files).length,changed_assets:changed,financial_policy_unchanged:true,protected_predecessor:true}));
